118.   snapshot(): readonly CartLine[] {
119.     // Deep-copy both the CartLine and its Product so callers mutating the
120.     // returned snapshot cannot reach back into the cart's internal state.
121.     return Array.from(this.lines.values()).map((line) => ({
122.       product: { ...line.product },
123.       quantity: line.quantity,
124.     }));
125.   }
