      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 400)], 1000)).toBe(300);
      expect(calc.computeShippingCents([makeLine("a", 500)], 1000)).toBe(300);
      expect(calc.computeShippingCents([makeLine("a", 501)], 1000)).toBe(500);
      expect(calc.computeShippingCents([makeLine("a", 1000)], 1000)).toBe(500);
      expect(calc.computeShippingCents([makeLine("a", 1001)], 1000)).toBe(1000);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      expect(calc.computeShippingCents([makeLine("a", 6000)], 1000)).toBe(2000);
    });

    it("defaults overflow to heaviest bracket cost", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 9999)], 1000)).toBe(1000);
    });

    it("sums weight across multiple lines", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 200 * 3 = 600 → second bracket (500 < 600 <= 1000) → 500
      expect(
        calc.computeShippingCents([makeLine("a", 200, 3)], 1000),
      ).toBe(500);
    });

    it("sorts brackets internally regardless of input order", () => {
      const unsorted = [
        { upToGrams: 5000, costCents: 1000 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ];
      const calc = new WeightBasedShippingCalculator(unsorted);
      expect(calc.computeShippingCents([makeLine("a", 400)], 1000)).toBe(300);
    });
  });
});

